1	//! Filesystem and preloaded-corpus loaders (Saga 12 step 001).
2	//!
3	//! Two builtins live here:
4	//!
5	//! - `load("relative-path")` reads a file under the
6	//!   `Environment::data_dir` sandbox. `.csv` files parse as numeric
7	//!   matrices (stripping a non-numeric header row if present);
8	//!   `.txt` files return their whole contents as a `Value::Str`.
9	//!   Absolute paths and `..`-traversal outside the sandbox error
10	//!   cleanly. When `data_dir` is `None` (the web REPL), `load`
11	//!   errors with a pointer to `load_preloaded`.
12	//! - `load_preloaded("name")` looks up a small in-memory corpus
13	//!   registry so the web REPL has a fs-free path for the
14	//!   Tokenizing-Text tutorial lesson in step 009.
15	
16	use std::path::{Component, Path, PathBuf};
17	
18	use mlpl_array::{DenseArray, Shape};
19	
20	use crate::env::Environment;
21	use crate::error::EvalError;
22	use crate::value::Value;
23	
24	/// Compiled-in preloaded corpora. Keeping the registry tiny and
25	/// explicit; the web REPL's WASM binary carries these as string
26	/// literals.
27	const PRELOADED: &[(&str, &str)] = &[
28	    (
29	        "tiny_corpus",
30	        "the quick brown fox jumps over the lazy dog.\n\
31	         pack my box with five dozen liquor jugs.\n",
32	    ),
33	    (
34	        "tiny_shakespeare_snippet",
35	        include_str!("../data/tiny_shakespeare_snippet.txt"),
36	    ),
37	];
38	
39	/// Dispatch `load(path)`. Called from `eval::eval_expr` when the
40	/// evaluator sees a `FnCall { name == "load", args.len() == 1 }`
41	/// whose single arg evaluates to a `Value::Str`.
42	pub(crate) fn eval_load(env: &Environment, path: &str) -> Result<Value, EvalError> {
43	    let Some(root) = env.data_dir() else {
44	        return Err(EvalError::Unsupported(format!(
45	            "load(\"{path}\"): filesystem access disabled (try load_preloaded(\"...\") \
46	             in the web REPL, or start the terminal REPL with --data-dir <path>)"
47	        )));
48	    };
49	    let resolved = resolve_in_sandbox(root, path)?;
50	    let contents = std::fs::read_to_string(&resolved)
51	        .map_err(|e| EvalError::Unsupported(format!("load(\"{path}\"): {e}")))?;
52	    if path.ends_with(".csv") {
53	        parse_csv(&contents, path).map(Value::Array)
54	    } else {
55	        Ok(Value::Str(contents))
56	    }
57	}
58	
59	/// Dispatch `load_preloaded(name)`.
60	pub(crate) fn eval_load_preloaded(name: &str) -> Result<Value, EvalError> {
61	    PRELOADED
62	        .iter()
63	        .find(|(k, _)| *k == name)
64	        .map(|(_, body)| Value::Str((*body).to_string()))
65	        .ok_or_else(|| {
66	            EvalError::Unsupported(format!(
67	                "load_preloaded(\"{name}\"): unknown preloaded corpus"
68	            ))
69	        })
70	}
71	
72	/// Resolve a caller-supplied relative path under a sandbox root.
73	/// Absolute paths and any component that escapes the root via `..`
74	/// are rejected.
75	fn resolve_in_sandbox(root: &Path, relative: &str) -> Result<PathBuf, EvalError> {
76	    let rel = Path::new(relative);
77	    if rel.is_absolute() {
78	        return Err(EvalError::Unsupported(format!(
79	            "load(\"{relative}\"): absolute paths are rejected; paths are relative \
80	             to the sandbox root {}",
81	            root.display()
82	        )));
83	    }
84	    // Walk components manually so we catch `..` escapes without
85	    // touching the filesystem (canonicalize would dereference
86	    // symlinks, which we don't want).
87	    let mut depth: i64 = 0;
88	    for comp in rel.components() {
89	        match comp {
90	            Component::Normal(_) | Component::CurDir => {
91	                depth += i64::from(matches!(comp, Component::Normal(_)))
92	            }
93	            Component::ParentDir => {
94	                depth -= 1;
95	                if depth < 0 {
96	                    return Err(EvalError::Unsupported(format!(
97	                        "load(\"{relative}\"): path escapes sandbox root {}",
98	                        root.display()
99	                    )));
100	                }
101	            }
102	            Component::RootDir | Component::Prefix(_) => {
103	                return Err(EvalError::Unsupported(format!(
104	                    "load(\"{relative}\"): rooted components not permitted inside \
105	                     sandbox {}",
106	                    root.display()
107	                )));
108	            }
109	        }
110	    }
111	    Ok(root.join(rel))
112	}
113	
114	/// Parse a CSV string into a 2-D `DenseArray`. Handles comma
115	/// delimiters only. If the first row contains any non-numeric
116	/// token it is treated as a header and skipped. Ragged rows or
117	/// non-numeric data rows surface as `EvalError::Unsupported`.
118	fn parse_csv(text: &str, path: &str) -> Result<DenseArray, EvalError> {
119	    let mut rows: Vec<Vec<String>> = text
120	        .lines()
121	        .filter(|line| !line.is_empty())
122	        .map(|line| line.split(',').map(|c| c.trim().to_string()).collect())
123	        .collect();
124	    if rows.is_empty() {
125	        return Err(EvalError::Unsupported(format!(
126	            "load(\"{path}\"): file contains no data rows"
127	        )));
128	    }
129	    // Header detection: if any first-row cell fails to parse as f64,
130	    // treat the first row as a header and drop it.
131	    let first_is_header = rows[0].iter().any(|cell| cell.parse::<f64>().is_err());
132	    if first_is_header {
133	        rows.remove(0);
134	        if rows.is_empty() {
135	            return Err(EvalError::Unsupported(format!(
136	                "load(\"{path}\"): header-only file with no data rows"
137	            )));
138	        }
139	    }
140	    let cols = rows[0].len();
141	    let mut data = Vec::with_capacity(rows.len() * cols);
142	    for (row_idx, row) in rows.iter().enumerate() {
143	        if row.len() != cols {
144	            return Err(EvalError::Unsupported(format!(
145	                "load(\"{path}\"): ragged rows (row {row_idx} has {} cols, \
146	                 expected {cols})",
147	                row.len()
148	            )));
149	        }
150	        for cell in row {
151	            let v: f64 = cell.parse().map_err(|_| {
152	                EvalError::Unsupported(format!(
153	                    "load(\"{path}\"): non-numeric cell \"{cell}\" at row {row_idx}"
154	                ))
155	            })?;
156	            data.push(v);
157	        }
158	    }
159	    DenseArray::new(Shape::new(vec![rows.len(), cols]), data).map_err(EvalError::ArrayError)
160	}
