1	//! Runtime value type for MLPL.
2	
3	use std::collections::BTreeMap;
4	use std::fmt;
5	
6	use mlpl_array::DenseArray;
7	
8	use crate::error::EvalError;
9	use crate::model::ModelSpec;
10	use crate::tokenizer::TokenizerSpec;
11	
12	/// A runtime value: an array, a string, a model, a tokenizer,
13	/// or a peer-resident device tensor reference.
14	#[derive(Clone, Debug, PartialEq)]
15	pub enum Value {
16	    /// A dense array (scalar, vector, matrix, ...).
17	    Array(DenseArray),
18	    /// A string (introduced for diagram type names, LLM prompts, etc.).
19	    Str(String),
20	    /// A model: a callable layer (or composition) with attached
21	    /// parameters held in the environment. Saga 11.
22	    Model(ModelSpec),
23	    /// A tokenizer (Saga 12 step 004). Sibling to `Model` -- holds
24	    /// the tokenization strategy as data.
25	    Tokenizer(TokenizerSpec),
26	    /// A reference to a builtin or operator. Produced by the
27	    /// `:foo` / `:+` / `:max` syntax. Higher-order builtins
28	    /// like `reduce` and `map` accept this in place of a
29	    /// (future) function value -- it is the canonical first-
30	    /// class-ish op handle in v0.19.
31	    BuiltinRef {
32	        /// The builtin name without the leading `:`. Examples:
33	        /// `"add"`, `"+"`, `"max"`, `"sigmoid"`.
34	        name: String,
35	    },
36	    /// Saga R1 step 002: peer-resident tensor reference. The bytes
37	    /// live on the peer named by `peer`; the orchestrator only holds
38	    /// the handle + shape + device metadata. Touching it from a CPU
39	    /// op errors strict-fault; explicit `to_device('cpu', x)` is the
40	    /// only way to materialize the bytes back as a `Value::Array`.
41	    DeviceTensor {
42	        /// Peer URL the bytes live on.
43	        peer: String,
44	        /// Opaque handle issued by the peer.
45	        handle: String,
46	        /// Tensor shape (orchestrator-side cached so callers can
47	        /// `shape(x)` without a network round-trip).
48	        shape: Vec<usize>,
49	        /// Device name (e.g., `"mlx"`, future `"cuda"`).
50	        device: String,
51	    },
52	    /// Saga 29 step 001: structured record value. Field names map
53	    /// to arbitrary values (including nested records). BTreeMap so
54	    /// the key ordering is deterministic for display, trace
55	    /// serialization, and equality testing.
56	    Record {
57	        /// Field name -> value, sorted by name.
58	        fields: BTreeMap<String, Value>,
59	    },
60	}
61	
62	impl Value {
63	    /// Extract the inner array, returning an error if this is a
64	    /// string, model, tokenizer, or device tensor.
65	    pub fn into_array(self) -> Result<DenseArray, EvalError> {
66	        match self {
67	            Self::Array(a) => Ok(a),
68	            Self::DeviceTensor { peer, device, .. } => {
69	                Err(EvalError::DeviceTensorFault { peer, device })
70	            }
71	            _ => Err(EvalError::ExpectedArray),
72	        }
73	    }
74	
75	    /// Borrow the inner array, returning an error if this is a
76	    /// string, model, tokenizer, or device tensor.
77	    pub fn as_array(&self) -> Result<&DenseArray, EvalError> {
78	        match self {
79	            Self::Array(a) => Ok(a),
80	            Self::DeviceTensor { peer, device, .. } => Err(EvalError::DeviceTensorFault {
81	                peer: peer.clone(),
82	                device: device.clone(),
83	            }),
84	            _ => Err(EvalError::ExpectedArray),
85	        }
86	    }
87	}
88	
89	impl From<DenseArray> for Value {
90	    fn from(a: DenseArray) -> Self {
91	        Self::Array(a)
92	    }
93	}
94	
95	/// Saga 29 step 001: human-readable variant name for tutoring
96	/// error messages (e.g., `FieldOnNonRecord`). Stable strings;
97	/// callers may match on them in tests.
98	pub fn value_kind(v: &Value) -> &'static str {
99	    match v {
100	        Value::Array(_) => "array",
101	        Value::Str(_) => "string",
102	        Value::Model(_) => "model",
103	        Value::Tokenizer(_) => "tokenizer",
104	        Value::BuiltinRef { .. } => "builtin-ref",
105	        Value::DeviceTensor { .. } => "device-tensor",
106	        Value::Record { .. } => "record",
107	    }
108	}
109	
110	impl From<String> for Value {
111	    fn from(s: String) -> Self {
112	        Self::Str(s)
113	    }
114	}
115	
116	impl fmt::Display for Value {
117	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
118	        match self {
119	            Self::Array(a) => write!(f, "{a}"),
120	            Self::Str(s) => write!(f, "{s}"),
121	            Self::Model(_) => write!(f, "<model>"),
122	            Self::Tokenizer(t) => write!(f, "<tokenizer: {}>", t.describe()),
123	            Self::BuiltinRef { name } => write!(f, ":{name}"),
124	            Self::DeviceTensor {
125	                peer,
126	                device,
127	                shape,
128	                ..
129	            } => write!(f, "<tensor on {peer}:{device}; shape={shape:?}>"),
130	            Self::Record { fields } => {
131	                write!(f, "{{")?;
132	                for (i, (name, value)) in fields.iter().enumerate() {
133	                    if i > 0 {
134	                        write!(f, ", ")?;
135	                    }
136	                    write!(f, "{name}: {value}")?;
137	                }
138	                write!(f, "}}")
139	            }
140	        }
141	    }
142	}
143

