        /// Peer URL the tensor lives on.
        peer: String,
        /// Device name on that peer (e.g., `"mlx"`).
        device: String,
    },
    /// Wrong number of arguments to a built-in.
    BadArity {
        /// Function name.
        func: String,
        /// Expected count.
        expected: usize,
        /// Got count.
        got: usize,
    },
