38	fn run_program(
39	    stmts: &[Expr],
40	    env: &mut Environment,
41	    mut trace: Option<&mut Trace>,
42	) -> Result<Value, EvalError> {
43	    if stmts.is_empty() {
44	        return Err(EvalError::EmptyInput);
45	    }
46	    let mut result = None;
47	    for stmt in stmts {
