53	pub(crate) fn eval_expr(
54	    expr: &Expr,
55	    env: &mut Environment,
56	    trace: &mut Option<&mut Trace>,
57	) -> Result<Value, EvalError> {
58	    if let Expr::StrLit(s, _) = expr {
59	        return Ok(Value::Str(s.clone()));
60	    }
61	    if let Expr::BuiltinRef(name, _) = expr {
62	        return Ok(Value::BuiltinRef { name: name.clone() });
63	    }
64	    if let Expr::RecordLit { fields, .. } = expr {
65	        let mut map = std::collections::BTreeMap::new();
66	        for (name, value_expr) in fields {
67	            let v = eval_expr(value_expr, env, trace)?;
68	            map.insert(name.clone(), v);
69	        }
70	        return Ok(Value::Record { fields: map });
71	    }
72	    // Saga 29 step 002: `[...]` array-literal dispatch.
73	    // Evaluate each element first, then decide based on the
74	    // resulting kinds:
75	    //   - all `Value::Str`  -> `Value::StrList`
76	    //   - all `Value::Array` (numeric) -> existing numeric
77	    //     flattening, with an `array_lit` trace event so the
78	    //     prior trace-event shape is preserved
79	    //   - empty `[]` keeps the back-compat numeric path
80	    //     (empty `DenseArray`)
81	    //   - mixed -> `MixedArrayLitElements`
82	    if let Expr::ArrayLit(elems, _) = expr {
83	        let arr_opt: Option<DenseArray> = if elems.is_empty() {
84	            Some(DenseArray::from_vec(vec![]))
85	        } else {
86	            let mut evaluated: Vec<Value> = Vec::with_capacity(elems.len());
87	            for e in elems {
88	                evaluated.push(eval_expr(e, env, trace)?);
89	            }
90	            if evaluated.iter().all(|v| matches!(v, Value::Str(_))) {
91	                let items: Vec<String> = evaluated
92	                    .into_iter()
93	                    .map(|v| match v {
94	                        Value::Str(s) => s,
95	                        _ => unreachable!(),
96	                    })
97	                    .collect();
98	                return Ok(Value::StrList { items });
99	            }
100	            if evaluated.iter().all(|v| matches!(v, Value::Array(_))) {
101	                let arrays: Vec<DenseArray> = evaluated
102	                    .into_iter()
103	                    .map(|v| match v {
104	                        Value::Array(a) => a,
105	                        _ => unreachable!(),
106	                    })
107	                    .collect();
108	                Some(flatten_evaluated_arrays(arrays)?)
109	            } else {
110	                let kinds: Vec<&'static str> = evaluated.iter().map(value_kind).collect();
111	                return Err(EvalError::MixedArrayLitElements { kinds });
112	            }
113	        };
114	        let arr = arr_opt.unwrap();
115	        if let Some(t) = trace.as_mut() {
116	            let seq = t.events().len() as u64;
117	            t.push(TraceEvent {
118	                seq,
119	                op: "array_lit".into(),
120	                span: expr.span(),
121	                inputs: vec![],
122	                output: TraceValue::from_array(&arr),
123	                input_types: vec![],
124	                output_type: None,
125	            });
126	        }
127	        return Ok(Value::Array(arr));
128	    }
129	    // Saga 29 step 002: `list_len(xs)` returns the length of a
