37	/// Compiled-in pets_tiny fixture. Built offline by
38	/// `scripts/build-pets-tiny.rs` from the gitignored
39	/// `data/oxford-iiit-pet/images/` checkout. Empty until that
40	/// script runs; the test gate (and any live caller) will
41	/// fail-fast with a clear message if so.
42	const PETS_TINY_BIN: &[u8] = include_bytes!("../data/pets_tiny.bin");
43	
44	/// Read the embedded fixture, expand the u8 pixel data to
45	/// f64 in [-1, 1], and return a `Value::Record` with fields
46	/// `X` ([N, 3, H, W] with axis labels), `Y` ([N]), and
47	/// `names` (a `Value::StrList`).
48	pub(crate) fn load() -> Result<Value, EvalError> {
49	    let (header, body) = parse_header(PETS_TINY_BIN)?;
50	    let Header { n, c, h, w } = header;
51	    let mut cursor = 0usize;
52	    if body.len() < n {
53	        return Err(corrupt("Y labels truncated"));
54	    }
55	    let y_bytes = &body[cursor..cursor + n];
56	    cursor += n;
57	    if body.len() < cursor + 4 {
58	        return Err(corrupt("name-table length missing"));
59	    }
60	    let names_len = u32::from_le_bytes([
61	        body[cursor],
62	        body[cursor + 1],
63	        body[cursor + 2],
64	        body[cursor + 3],
65	    ]) as usize;
66	    cursor += 4;
67	    if body.len() < cursor + names_len {
68	        return Err(corrupt("name-table truncated"));
69	    }
70	    let names_bytes = &body[cursor..cursor + names_len];
71	    cursor += names_len;
72	    let per_image = c * h * w;
73	    let pixel_bytes = n * per_image;
74	    if body.len() < cursor + pixel_bytes {
75	        return Err(corrupt("pixel data truncated"));
76	    }
77	    let pixels = &body[cursor..cursor + pixel_bytes];
78	
79	    let names: Vec<String> = if names_len == 0 {
80	        Vec::new()
81	    } else {
82	        names_bytes
83	            .split(|b| *b == 0)
84	            .filter(|s| !s.is_empty())
85	            .map(|s| String::from_utf8_lossy(s).into_owned())
86	            .collect()
87	    };
88	
89	    // X: u8 -> f64 in [-1, 1]
90	    let mut x_data = Vec::with_capacity(pixel_bytes);
91	    for &b in pixels {
92	        x_data.push(f64::from(b) / 127.5 - 1.0);
93	    }
94	    let x_arr = DenseArray::new(Shape::new(vec![n, c, h, w]), x_data)?.with_labels(vec![
95	        Some("batch".to_string()),
96	        Some("channel".to_string()),
97	        Some("y".to_string()),
98	        Some("x".to_string()),
99	    ])?;
100	
101	    let y_data: Vec<f64> = y_bytes.iter().map(|b| f64::from(*b)).collect();
102	    let y_arr = DenseArray::new(Shape::new(vec![n]), y_data)?
103	        .with_labels(vec![Some("batch".to_string())])?;
104	
105	    let mut fields = BTreeMap::new();
106	    fields.insert("X".to_string(), Value::Array(x_arr));
107	    fields.insert("Y".to_string(), Value::Array(y_arr));
108	    fields.insert("names".to_string(), Value::StrList { items: names });
109	    Ok(Value::Record { fields })
110	}
