112	struct Header {
113	    n: usize,
114	    c: usize,
115	    h: usize,
116	    w: usize,
117	}
118	
119	fn parse_header(bytes: &[u8]) -> Result<(Header, &[u8]), EvalError> {
120	    if bytes.is_empty() {
121	        return Err(EvalError::Unsupported(
122	            "load_preloaded(\"pets_tiny\"): fixture is empty -- run \
123	             scripts/build-pets-tiny.rs against the gitignored \
124	             data/oxford-iiit-pet/ checkout to populate it"
125	                .into(),
126	        ));
127	    }
128	    if bytes.len() < 8 + 4 + 16 {
129	        return Err(corrupt("file shorter than header"));
130	    }
131	    if &bytes[..8] != MAGIC {
132	        return Err(corrupt("bad magic bytes"));
133	    }
134	    let version = u32::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]]);
135	    if version != VERSION {
136	        return Err(EvalError::Unsupported(format!(
137	            "load_preloaded(\"pets_tiny\"): version {version} not supported (this build expects {VERSION})"
138	        )));
139	    }
140	    let read_u32 = |o: usize| {
141	        u32::from_le_bytes([bytes[o], bytes[o + 1], bytes[o + 2], bytes[o + 3]]) as usize
142	    };
143	    let n = read_u32(12);
144	    let c = read_u32(16);
145	    let h = read_u32(20);
146	    let w = read_u32(24);
147	    Ok((Header { n, c, h, w }, &bytes[28..]))
148	}
149	
150	fn corrupt(msg: &str) -> EvalError {
151	    EvalError::Unsupported(format!(
152	        "load_preloaded(\"pets_tiny\"): corrupt fixture ({msg})"
153	    ))
154	}

