1	//! `fetch_dataset(name)` -- download + verify + extract +
2	//! decode the Oxford-IIIT Pet dataset at the demo's 128x128
3	//! resolution. Saga 29 step 004.
4	//!
5	//! Native-only via the `image-io` Cargo feature; the WASM
6	//! REPL gets a clean error pointing at
7	//! `load_preloaded("pets_tiny")` instead. The pipeline
8	//! caches by file existence -- if the tarball is already
9	//! sitting in `$MLPL_DATA_DIR/oxford-iiit-pet/images.tar.gz`
10	//! (sha256-verified), we skip the download; if
11	//! `images/` is already extracted, we skip the extract. So
12	//! repeat calls within a session are cheap, and a
13	//! pre-populated `data/oxford-iiit-pet/` checkout (the
14	//! gitignored layout that step 003 set up) bypasses HTTP
15	//! entirely.
16	//!
17	//! Dataset resolution: each name maps to a `DatasetSpec`
18	//! that records the canonical upstream URL, the sha256 of
19	//! the tarball we know how to handle, the on-disk layout,
20	//! and the demo's target resolution. Adding a new dataset
21	//! is a single-line entry plus a test fixture; we deliberately
22	//! keep the registry tiny.
23	
24	#![cfg(feature = "image-io")]
25	
26	use std::collections::BTreeMap;
27	use std::fs;
28	use std::io::{Read, Write};
29	use std::path::{Path, PathBuf};
30	
31	use mlpl_array::{DenseArray, Shape};
32	use sha2::Digest;
33	
34	use crate::env::Environment;
35	use crate::error::EvalError;
36	use crate::value::Value;
37	
38	const OXFORD_PET_URL: &str = "https://www.robots.ox.ac.uk/~vgg/data/pets/data/images.tar.gz";
39	const OXFORD_PET_SHA256: &str = "67195c5e1c01f1ab5f9b6a5d22b8c27a580d896ece458917e61d459337fa318d";
40	const OXFORD_PET_H: usize = 128;
41	const OXFORD_PET_W: usize = 128;
42	
43	struct DatasetSpec {
44	    url: &'static str,
45	    sha256: &'static str,
46	    /// Relative subdir under `$MLPL_DATA_DIR` for everything
47	    /// related to this dataset.
48	    subdir: &'static str,
49	    /// Tarball filename inside the subdir.
50	    tarball: &'static str,
51	    /// Image-bearing subdirectory inside the tarball (after
52	    /// extract).
53	    images_subdir: &'static str,
54	    target_h: usize,
55	    target_w: usize,
56	}
57	
58	fn lookup(name: &str) -> Result<DatasetSpec, EvalError> {
59	    match name {
60	        "oxford_iiit_pet" => Ok(DatasetSpec {
61	            url: OXFORD_PET_URL,
62	            sha256: OXFORD_PET_SHA256,
63	            subdir: "oxford-iiit-pet",
64	            tarball: "images.tar.gz",
65	            images_subdir: "images",
66	            target_h: OXFORD_PET_H,
67	            target_w: OXFORD_PET_W,
68	        }),
69	        _ => Err(EvalError::Unsupported(format!(
70	            "fetch_dataset(\"{name}\"): unknown dataset (the v0.21 \
71	             registry only ships \"oxford_iiit_pet\"; PRs welcome)"
72	        ))),
73	    }
74	}
75	
76	/// Entry point called from `eval::eval_expr`.
77	pub(crate) fn eval(env: &Environment, name: &str) -> Result<Value, EvalError> {
78	    let spec = lookup(name)?;
79	    let root = resolve_data_root(env, name)?;
80	    let dataset_root = root.join(spec.subdir);
81	    fs::create_dir_all(&dataset_root).map_err(|e| io_err(&dataset_root, e))?;
82	    let tarball_path = dataset_root.join(spec.tarball);
83	    let images_path = dataset_root.join(spec.images_subdir);
84	    ensure_tarball(&tarball_path, spec.url, spec.sha256)?;
85	    if !images_path.exists() {
86	        extract_tarball(&tarball_path, &dataset_root)?;
87	    }
88	    decode_directory_to_record(&images_path, spec.target_h, spec.target_w)
89	}
90	
91	/// Resolve where dataset files live. Priority: `$MLPL_DATA_DIR`
92	/// environment variable; then the `Environment::data_dir`
93	/// sandbox set via `--data-dir`. Without either, raise a
94	/// clean tutoring error -- a 792 MB download should never be
95	/// implicit.
96	fn resolve_data_root(env: &Environment, name: &str) -> Result<PathBuf, EvalError> {
97	    if let Ok(dir) = std::env::var("MLPL_DATA_DIR")
98	        && !dir.is_empty()
99	    {
100	        return Ok(PathBuf::from(dir));
101	    }
102	    if let Some(p) = env.data_dir() {
103	        return Ok(p.clone());
104	    }
105	    Err(EvalError::Unsupported(format!(
106	        "fetch_dataset(\"{name}\"): no data directory configured. \
107	         Set the MLPL_DATA_DIR env var (where the tarball will be \
108	         cached) or start the terminal REPL with --data-dir <path>."
109	    )))
110	}
111	
112	/// Download the tarball to `path` if it isn't already there.
113	/// Always verifies sha256 -- if a stale file is sitting at
114	/// the path with the wrong hash, we error rather than silently
115	/// trust it.
116	fn ensure_tarball(path: &Path, url: &str, expected_sha256: &str) -> Result<(), EvalError> {
117	    if path.exists() {
118	        let got = sha256_of(path)?;
119	        if got == expected_sha256 {
120	            return Ok(());
121	        }
122	        return Err(EvalError::Unsupported(format!(
123	            "fetch_dataset: {} sha256 mismatch (expected {expected_sha256}, \
124	             got {got}). Delete the file and retry.",
125	            path.display()
126	        )));
127	    }
128	    let resp = ureq::get(url)
129	        .call()
130	        .map_err(|e| EvalError::Unsupported(format!("fetch_dataset: HTTP GET {url}: {e}")))?;
131	    let mut reader = resp.into_reader();
132	    let mut buf = Vec::new();
133	    reader
134	        .read_to_end(&mut buf)
135	        .map_err(|e| EvalError::Unsupported(format!("fetch_dataset: read body from {url}: {e}")))?;
136	    let got = format!("{:x}", sha2::Sha256::digest(&buf));
137	    if got != expected_sha256 {
138	        return Err(EvalError::Unsupported(format!(
139	            "fetch_dataset: downloaded {url} but sha256 was {got} \
140	             (expected {expected_sha256})"
141	        )));
142	    }
143	    let mut f = fs::File::create(path).map_err(|e| io_err(path, e))?;
144	    f.write_all(&buf).map_err(|e| io_err(path, e))?;
145	    Ok(())
146	}
147	
148	fn sha256_of(path: &Path) -> Result<String, EvalError> {
149	    let mut f = fs::File::open(path).map_err(|e| io_err(path, e))?;
150	    let mut hasher = sha2::Sha256::new();
151	    let mut buf = vec![0u8; 64 * 1024];
152	    loop {
153	        let n = f.read(&mut buf).map_err(|e| io_err(path, e))?;
154	        if n == 0 {
155	            break;
156	        }
157	        hasher.update(&buf[..n]);
158	    }
159	    Ok(format!("{:x}", hasher.finalize()))
160	}
161	
162	fn extract_tarball(tar_path: &Path, dest: &Path) -> Result<(), EvalError> {
163	    let f = fs::File::open(tar_path).map_err(|e| io_err(tar_path, e))?;
164	    let gz = flate2::read::GzDecoder::new(f);
165	    let mut archive = tar::Archive::new(gz);
166	    archive.unpack(dest).map_err(|e| {
167	        EvalError::Unsupported(format!(
168	            "fetch_dataset: tar extract {} -> {}: {e}",
169	            tar_path.display(),
170	            dest.display()
171	        ))
172	    })?;
173	    Ok(())
174	}
