fn decode_directory_to_record(images_dir: &Path, h: usize, w: usize) -> Result<Value, EvalError> {
    let mut paths: Vec<PathBuf> = fs::read_dir(images_dir)
        .map_err(|e| io_err(images_dir, e))?
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| {
            p.extension()
                .and_then(|e| e.to_str())
                .map(|e| {
                    let e = e.to_ascii_lowercase();
                    e == "png" || e == "jpg" || e == "jpeg"
                })
                .unwrap_or(false)
        })
        .collect();
    paths.sort();
    if paths.is_empty() {
        return Err(EvalError::Unsupported(format!(
            "fetch_dataset: no PNG or JPEG files in {}",
            images_dir.display()
        )));
    }
    let per_image = 3 * h * w;
    let mut x_data: Vec<f64> = Vec::with_capacity(paths.len() * per_image);
    let mut y_data: Vec<f64> = Vec::with_capacity(paths.len());
    let mut names: Vec<String> = Vec::with_capacity(paths.len());
    for path in &paths {
        let pixels = crate::image_io::decode_and_resize(path, h, w)?;
        x_data.extend_from_slice(&pixels);
        let name = path.file_name().and_then(|n| n.to_str()).ok_or_else(|| {
            EvalError::Unsupported(format!(
                "fetch_dataset: non-utf8 filename {}",
                path.display()
            ))
        })?;
        y_data.push(label_for(name) as f64);
        names.push(name.to_string());
    }
    let x_arr =
        DenseArray::new(Shape::new(vec![paths.len(), 3, h, w]), x_data)?.with_labels(vec![
            Some("batch".to_string()),
            Some("channel".to_string()),
            Some("y".to_string()),
            Some("x".to_string()),
        ])?;
    let y_arr = DenseArray::new(Shape::new(vec![paths.len()]), y_data)?
        .with_labels(vec![Some("batch".to_string())])?;
    let mut fields = BTreeMap::new();
    fields.insert("X".to_string(), Value::Array(x_arr));
    fields.insert("Y".to_string(), Value::Array(y_arr));
    fields.insert("names".to_string(), Value::StrList { items: names });
    Ok(Value::Record { fields })
}

